D.Quests[31833]={Title="继续训练：吴大师",Objectives="和晴日峰的吴大师谈一谈，和她一起完成你的训练。",Description="欢迎回来，$n。你该开始下一阶段的训练了。去我们下方的训练场找吴大师学习新的课程吧。"}
D.Quests[31834]={Title="开始训练：程大师",Objectives="和训练场里的程大师谈一谈，和他一起完成你的训练。",Description="你好，$n。欢迎来到晴日峰，这里就是我们武僧修身养性、勤练武艺的地方。现在是时候开始你的训练了。和下面训练场里的程大师谈一谈，开始你的训练。"}
D.Quests[31835]={Title="继续训练：吉斯坦大师",Objectives="和晴日峰的吉斯坦大师谈一谈，和她一起完成你的训练。",Description="欢迎回来，$n。你该开始下一阶段的训练了。去我们下方的习武场找吉斯坦大师学习新的课程吧。"}
